<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A')
const dual=ref(true)
const selected=ref(0)
const state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const primary=computed(()=>dataset.value==='A'?[35,48,41,61,56,74]:[42,36,55,48,72,64])
const secondary=computed(()=>dataset.value==='A'?[20,28,25,39,33,46]:[26,19,35,28,43,36])
const x=(i:number)=>40+i*48
const y=(v:number)=>170-v*1.4
const points=(values:number[])=>values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')
function reset(){dataset.value='A';dual.value=true;selected.value=0;state.value='ready'}
</script>
<template>
<section class="line-chart-demo" aria-label="Local line chart example"><p>Synthetic monthly units. Straight segments join observations, not measurements between them.</p><div class="line-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label><input v-model="dual" type="checkbox">Show secondary</label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="line-legend"><span>Solid: Primary</span><span v-if="dual">Dashed: Secondary</span></div><svg :key="dataset+'-'+dual" viewBox="0 0 320 210" role="img" aria-label="Synthetic monthly units, January to June, fixed scale 0 to 100. Exact values are in the table below."><g v-for="tick in [0,25,50,75,100]" :key="tick"><line x1="36" x2="292" :y1="y(tick)" :y2="y(tick)" class="line-grid"/><text x="4" :y="y(tick)+4">{{ tick }}</text></g><text v-for="(label,i) in labels" :key="label" :x="x(i)" y="194" text-anchor="middle">{{ label }}</text><polyline :points="points(primary)" class="line-primary"/><polyline v-if="dual" :points="points(secondary)" class="line-secondary"/><circle v-for="(v,i) in primary" :key="i" :cx="x(i)" :cy="y(v)" :r="selected===i?5:3" class="line-dot"/></svg><div role="group" aria-label="Select month" class="line-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Primary {{ primary[selected] }} units<template v-if="dual">, Secondary {{ secondary[selected] }} units</template>.</p><table class="line-data"><caption>Exact sample values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col">Primary units</th><th v-if="dual" scope="col">Secondary units</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ primary[i] }}</td><td v-if="dual">{{ secondary[i] }}</td></tr></tbody></table></template><p v-else role="status" class="line-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.line-chart-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.line-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.line-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.line-chart-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.line-chart-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.line-chart-demo :is(button,select,input):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.line-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.line-chart-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:line-chart-in .2s ease-out}.line-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.line-chart-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.line-primary,.line-secondary{fill:none;stroke:var(--vp-c-brand-1);stroke-width:2.5}.line-secondary{stroke:var(--vp-c-text-2);stroke-dasharray:5 4}.line-dot{fill:var(--vp-c-brand-1);stroke:var(--vp-c-bg);stroke-width:1}.line-months{display:flex;gap:6px;flex-wrap:wrap}.line-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.line-data{display:table!important;width:100%;font-size:12px}.line-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.line-data :is(td,th){padding:6px 8px!important}.line-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes line-chart-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.line-chart-demo svg{animation:none}}
</style>
